"""Publish a new, self-contained frozen runtime/evidence bundle after every writer has stopped. No Java executes."""

import argparse
import json
import os
from pathlib import Path
import shutil
import tempfile

from runtime_bundle_io import (HERE, ROOT, PHASE, MANIFEST, Inventory, catalog, file_hash, import_path, json_bytes,
                               portable, publish_no_replace, require, sha_bytes)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo', type=Path, default=ROOT)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--report', action='append', required=True)
    parser.add_argument('--decision', required=True)
    parser.add_argument('--selected-source-record', required=True)
    parser.add_argument('--selected-production', choices=['original', 'compact'], required=True)
    args = parser.parse_args()
    repo = args.repo.resolve(strict=True)
    output = args.output.parent.resolve(strict=True) / args.output.name
    require(not output.exists() and not output.is_relative_to(repo), 'Output must be new and outside the checkout')
    inventory = Inventory(repo)
    identities = catalog(repo, inventory)
    materializer = 'core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializer.java'
    selected = PHASE + ('/runtimes/compact-page/modified-sources/' if args.selected_production == 'compact'
                        else '/baseline/preimages/') + materializer
    selected_digest = inventory.add(selected)['sha256']
    require(inventory.add(materializer)['sha256'] == selected_digest, 'Selected active production differs from decision')
    frame = 'core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation/codegen/KernelResultCoordinates.java'
    require(inventory.add(frame)['sha256'] == inventory.add(PHASE + '/baseline/preimages/' + frame)['sha256'],
            'Previously rejected frame guard entered selected production')
    inventory.add(PHASE + '/baseline/git-status.bin')
    # Include every text source, raw result and provenance record for this phase; never live stores or heaps.
    inventory.add_text_tree(PHASE)
    for relative in (
        'result-coordinate-evidence/materializer-followup/runtime_identity.py',
        'result-coordinate-evidence/materializer-followup/comparison_runtime_io.py',
        'result-coordinate-evidence/materializer-followup/bundle-comparison-runtime.py',
        'result-coordinate-evidence/materializer-followup/baseline/preimages/core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializer.java',
        'result-coordinate-evidence/final-validation/benchmark-source-hashes.json',
        'result-coordinate-evidence/transport-comparison/classpath-manifest.json',
        'result-coordinate-evidence/root-qualified-launcher/classpath.txt',
        'core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/benchmark/OptionalFanoutFixture.java',
        'core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/benchmark/OptionalFanoutExperimentFixture.java',
        'core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/benchmark/OptionalFanoutExperiment.java',
        'core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/evaluation/OptionalFanoutRouteAccess.java',
    ):
        inventory.add(relative)
    inventory.add_text_tree('result-coordinate-evidence/root-qualified-launcher/src')
    for relative in args.report + [args.decision, args.selected_source_record]:
        inventory.read(portable(relative)).decode('utf-8')
    inventory.assert_stable()
    manifest = {'format': 1, 'archivePrefix': 'rdf4j', 'originalRepository': str(repo),
                'selfContainedRuntime': True, 'jdkIncluded': False, 'storesIncluded': False,
                'candidatePromoted': args.selected_production == 'compact', 'activeProduction': args.selected_production,
                'selectedMaterializerSourceSha256': selected_digest,
                'runtimeArtifacts': identities['artifacts'], 'runtimes': identities['runtimes'],
                'commands': identities['commands'], 'rawCompilerOutputs': identities['rawCompilerOutputs'],
                'primaryProtocolSha256': identities['primaryProtocolSha256'],
                'selectionDecision': args.decision, 'selectedSourceRecord': args.selected_source_record, 'reports': args.report,
                'relocationHelper': PHASE + '/delivery/verify-and-relocate-runtime.py',
                'files': [inventory.files[key] for key in sorted(inventory.files)]}
    generated = json_bytes(manifest)
    name = 'rdf4j/' + MANIFEST
    files = {record['path']: record for record in manifest['files']}
    require(name not in files, 'Generated manifest conflicts with an input')
    files[name] = {'path': name, 'mode': 0o644, 'size': len(generated), 'sha256': sha_bytes(generated)}
    old_archive = import_path('verified_archive_helpers', repo / 'result-coordinate-evidence/materializer-followup/bundle-comparison-runtime.py')
    staging = Path(tempfile.mkdtemp(prefix='.compact-page-runtime-', dir=output.parent))
    published = False
    try:
        archive_name = 'rdf4j-compact-page-runtime.tar.gz'
        archive = staging / archive_name
        old_archive.write_archive(archive, repo, files, {name: generated})
        verification = old_archive.readback(archive, files, identities['artifacts'])
        inventory.assert_stable()
        (staging / 'runtime-bundle-manifest.json').write_bytes(generated)
        receipt = {'format': 1, 'archive': {'file': archive_name, 'bytes': archive.stat().st_size,
                                           'sha256': file_hash(archive)},
                   'manifestSha256': sha_bytes(generated), 'readback': verification,
                   'uniqueClasspathArtifacts': len(identities['artifacts']),
                   'runtimeCompositions': len(identities['runtimes']), 'recordedCommands': len(identities['commands']),
                   'sourceInputsStable': True, 'noJavaBuildOrTestExecuted': True,
                   'allPreviousDeliveriesPreserved': True}
        receipt_bytes = json_bytes(receipt)
        (staging / 'runtime-verification.json').write_bytes(receipt_bytes)
        hashes = {archive_name: receipt['archive']['sha256'], 'runtime-bundle-manifest.json': sha_bytes(generated),
                  'runtime-verification.json': sha_bytes(receipt_bytes)}
        (staging / 'SHA256SUMS').write_text(''.join(hashes[name] + '  ' + name + '\n' for name in sorted(hashes)))
        inventory.assert_stable()
        publish_no_replace(staging, output)
        published = True
        print(json.dumps(receipt, indent=2))
    finally:
        if not published:
            shutil.rmtree(staging)


if __name__ == '__main__':
    main()
